class HealthCheckIn(BaseModel):
    """Inputs of "Credential check".

    The reserved id the platform calls from the credential page's "Test" button and from "check credentials" in a workflow. It takes no input. An unusable credential must come back as **ok=false**, not as an error — an error leaves the platform able to say only "the call failed", not whether the key expired or the network is down. A plugin without this operation can only discover a stale credential through a real call."""

    pass


class HealthCheckOut(BaseModel):
    """Outputs of "Credential check".

    The reserved id the platform calls from the credential page's "Test" button and from "check credentials" in a workflow. It takes no input. An unusable credential must come back as **ok=false**, not as an error — an error leaves the platform able to say only "the call failed", not whether the key expired or the network is down. A plugin without this operation can only discover a stale credential through a real call."""

    # Usable
    ok: bool
    # Detail Say why when it is unusable; may be empty when it is fine
    message: str = ""


HealthCheckHandler = Callable[[Ctx, HealthCheckIn], Union[HealthCheckOut, Awaitable[Optional[HealthCheckOut]], None]]


def on_health_check(p: Plugin, fn: HealthCheckHandler) -> None:
    """Register the implementation of "Credential check". The handler may be an async def or a plain function."""

    async def _invoke(ctx: Ctx, raw: Dict[str, Any], out: Emitter) -> None:
        res = fn(ctx, HealthCheckIn.model_validate(raw))
        if inspect.isawaitable(res):
            res = await res
        if res is not None:
            out.vars(res)

    p.register("health_check", _invoke)


