class HeartbeatEvent(BaseModel):
    """Payload of the "Heartbeat" event"""

    # Chat ID
    chat_id: str
    # Timestamp
    at: str


async def trigger_heartbeat(ctx: SourceCtx, event_id: str, payload: HeartbeatEvent) -> None:
    """Push one "Heartbeat" event. event_id is the idempotency key: re-pushing the same upstream message triggers once."""
    await ctx.trigger("heartbeat", event_id, payload)


class MessageEvent(BaseModel):
    """Payload of the "Message received" event"""

    # Chat ID
    chat_id: str
    # Text
    text: str = ""
    # Attachment
    attachment: Optional[File] = None


async def trigger_message(ctx: SourceCtx, event_id: str, payload: MessageEvent) -> None:
    """Push one "Message received" event. event_id is the idempotency key: re-pushing the same upstream message triggers once."""
    await ctx.trigger("message", event_id, payload)


def new_plugin(**kwargs: Any) -> Plugin:
    """Build a plugin instance from this contract. Same as Plugin(CONTRACT, **kwargs)."""
    return Plugin(CONTRACT, **kwargs)
